import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

const user = { email: 'a@example.com', name: 'Alice' };

describe('users API', () => {
  it('creates, gets, updates and deletes users', async () => {
    const app = createApp();
    const created = await request(app).post('/v1/users').send(user).expect(201);
    expect(created.headers.location).toMatch(/^\/v1\/users\/.+/);
    expect(created.body).toMatchObject({ ...user, role: 'member' });
    const id = created.body.id;
    await request(app).get(`/v1/users/${id}`).expect(200);
    const patched = await request(app).patch(`/v1/users/${id}`).send({ name: 'A' }).expect(200);
    expect(patched.body.name).toBe('A');
    await request(app).delete(`/v1/users/${id}`).expect(204);
    await request(app).get(`/v1/users/${id}`).expect(404).expect('Content-Type', /application\/problem\+json/);
  });

  it('validates fields, conflicts, malformed JSON and missing ids', async () => {
    const app = createApp();
    const bad = await request(app).post('/v1/users').send({ email: 'bad', name: '' }).expect(422);
    expect(bad.body.detail).toContain('email'); expect(bad.body.detail).toContain('name');
    await request(app).post('/v1/users').set('Content-Type', 'application/json').send('{').expect(400);
    await request(app).get('/v1/users/nope').expect(404);
    await request(app).patch('/v1/users/nope').send({ name: 'x' }).expect(404);
    await request(app).delete('/v1/users/nope').expect(404);
    await request(app).post('/v1/users').send(user).expect(201);
    await request(app).post('/v1/users').send(user).expect(409);
    await request(app).patch('/v1/users/nope').send({}).expect(404);
  });

  it('paginates and honors idempotency', async () => {
    const app = createApp();
    const first = await request(app).post('/v1/users').set('Idempotency-Key', 'k').send(user).expect(201);
    const replay = await request(app).post('/v1/users').set('Idempotency-Key', 'k').send(user).expect(201);
    expect(replay.headers['idempotent-replayed']).toBe('true'); expect(replay.body.id).toBe(first.body.id);
    await request(app).post('/v1/users').set('Idempotency-Key', 'k').send({ ...user, name: 'Other' }).expect(422);
    for (let i = 0; i < 2; i++) await request(app).post('/v1/users').send({ email: `${i}@e.com`, name: `N${i}` }).expect(201);
    const page = await request(app).get('/v1/users?limit=2').expect(200);
    expect(page.body.data).toHaveLength(2);
    if (page.body.nextCursor) expect((await request(app).get(`/v1/users?limit=2&cursor=${page.body.nextCursor}`)).body.data).toHaveLength(1);
    await request(app).get('/v1/users?limit=101').expect(422);
    await request(app).patch(`/v1/users/${first.body.id}`).send({}).expect(422);
  });
});

import type { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';

const UserSchema = z.object({ id: z.string().uuid(), email: z.string().email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']), createdAt: z.string().datetime(), updatedAt: z.string().datetime() });
const CreateSchema = z.object({ email: z.string().email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']).default('member') }).strict();
const PatchSchema = z.object({ email: z.string().email().optional(), name: z.string().min(1).max(100).optional(), role: z.enum(['admin', 'member']).optional() }).strict().refine((v) => Object.keys(v).length > 0, { message: 'At least one field is required', path: ['body'] });
const IdSchema = z.object({ userId: z.string().uuid() });
const PageSchema = pageSchema(UserSchema);
type User = z.infer<typeof UserSchema>;

export function registerRoutes(app: Router): void {
  const users: User[] = [];
  const find = (req: Request): User => { const { userId } = IdSchema.parse(req.params); const user = users.find((u) => u.id === userId); if (user === undefined) throw notFound(`User ${userId} was not found.`); return user; };
  app.post('/v1/users', idempotency(), (req: Request, res: Response) => { const input = CreateSchema.parse(req.body); if (users.some((u) => u.email === input.email)) throw conflict('email: A user with this email already exists.'); const now = new Date().toISOString(); const user = UserSchema.parse({ ...input, id: crypto.randomUUID(), createdAt: now, updatedAt: now }); users.push(user); res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user)); });
  app.get('/v1/users', (req: Request, res: Response) => { const query = CursorQuerySchema.parse(req.query); res.json(PageSchema.parse(paginate(users, query, (u) => `${u.createdAt}|${u.id}`))); });
  app.get('/v1/users/:userId', (req: Request, res: Response) => res.json(UserSchema.parse(find(req))));
  app.patch('/v1/users/:userId', idempotency(), (req: Request, res: Response) => { const user = find(req); const input = PatchSchema.parse(req.body); if (input.email !== undefined && users.some((u) => u.id !== user.id && u.email === input.email)) throw conflict('email: A user with this email already exists.'); Object.assign(user, input, { updatedAt: new Date().toISOString() }); res.json(UserSchema.parse(user)); });
  app.delete('/v1/users/:userId', (req: Request, res: Response) => { const user = find(req); users.splice(users.indexOf(user), 1); res.status(204).send(); });
}

